css:
.tuathasim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2e2a22;
    background:
        radial-gradient(circle at 80% 0%, #e9efd9 0%, rgba(233,239,217,0) 45%),
        linear-gradient(165deg, #f6f3e9 0%, #eee7d6 55%, #e6dcc4 100%);
    border-radius: 18px;
}

.tuathasim-container * {
    box-sizing: border-box;
}

.tuathasim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #2f4a2c 0%, #3d5d34 50%, #6b7a3a 100%);
    color: #f4f7e8;
    border-radius: 16px;
    margin-bottom: 20px;
    border: 1px solid #2a3f26;
    box-shadow: 0 12px 34px rgba(47, 74, 44, 0.30);
}

.tuathasim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.4px;
    color: #fbfdf2;
}

.tuathasim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #d9e6a8;
    background: rgba(217, 230, 168, 0.14);
    border: 1px solid rgba(217, 230, 168, 0.32);
    padding: 5px 14px;
    border-radius: 999px;
}

.tuathasim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.56;
    color: #e6ecd2;
}

.tuathasim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #5e5640;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.tuathasim-period-counter #currentDay,
.tuathasim-period-counter #maxPeriods {
    font-weight: 800;
    color: #3d5d34;
}

.tuathasim-round-name {
    background: rgba(61, 93, 52, 0.12);
    color: #3d5d34;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.tuathasim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a5a1e;
    background: rgba(186, 122, 41, 0.14);
    border: 1px solid rgba(186, 122, 41, 0.34);
    padding: 4px 12px;
    border-radius: 999px;
}

.tuathasim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.tuathasim-status-card {
    background: linear-gradient(160deg, #ffffff 0%, #f4f1e4 100%);
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #ded3b8;
    box-shadow: 0 6px 16px rgba(90, 80, 50, 0.12);
    border-top: 4px solid #6b7a3a;
}

.tuathasim-card-rep { border-top-color: #b07b2c; }
.tuathasim-card-legit { border-top-color: #3d5d34; }
.tuathasim-card-margin { border-top-color: #4f6f8f; }
.tuathasim-card-voice { border-top-color: #7d4f86; }

.tuathasim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a8060;
}

.tuathasim-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.08;
    margin: 4px 0 2px;
    color: #2e2a22;
    font-variant-numeric: tabular-nums;
}

.tuathasim-card-rep .tuathasim-value { color: #b07b2c; }
.tuathasim-card-legit .tuathasim-value { color: #3d5d34; }
.tuathasim-card-margin .tuathasim-value { color: #4f6f8f; }
.tuathasim-card-voice .tuathasim-value { color: #7d4f86; }

.tuathasim-sublabel {
    font-size: 0.76rem;
    color: #7a7155;
    line-height: 1.35;
}

.tuathasim-legit-high { border-top-color: #2e7d32; }
.tuathasim-legit-high .tuathasim-value { color: #2e7d32; }
.tuathasim-legit-low { border-top-color: #b23a2e; }
.tuathasim-legit-low .tuathasim-value { color: #b23a2e; }

.tuathasim-margin-negative .tuathasim-value { color: #b23a2e; }
.tuathasim-margin-positive .tuathasim-value { color: #4f6f8f; }

.tuathasim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #efe9d6;
    border: 1px solid #ded3b8;
    color: #5e5640;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.tuathasim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #8a5a1e;
}

.tuathasim-briefing {
    display: flex;
    gap: 14px;
    background: linear-gradient(160deg, #ffffff 0%, #f3f0e2 100%);
    border-left: 5px solid #6b7a3a;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(90, 80, 50, 0.12);
}

.tuathasim-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.tuathasim-briefing-title {
    font-weight: 800;
    font-size: 1.1rem;
    color: #2f4a2c;
    margin-bottom: 6px;
}

.tuathasim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.56;
    color: #4b4636;
}

.tuathasim-briefing-text strong { color: #3d5d34; }
.tuathasim-briefing-text em { color: #8a5a1e; font-style: italic; }

.tuathasim-controls {
    background: linear-gradient(160deg, #fbf9f0 0%, #f1ecdc 100%);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #ded3b8;
    box-shadow: 0 6px 16px rgba(90, 80, 50, 0.12);
}

.tuathasim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #2f4a2c;
    border-bottom: 2px solid #ded3b8;
    padding-bottom: 8px;
}

.tuathasim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #3b3727;
    margin: 14px 0 6px;
}

.tuathasim-container select,
.tuathasim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c9bd9d;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fffdf6;
    color: #2e2a22;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.tuathasim-container select:focus,
.tuathasim-container input[type="number"]:focus {
    outline: none;
    border-color: #6b7a3a;
    box-shadow: 0 0 0 3px rgba(107, 122, 58, 0.20);
}

.tuathasim-container select option {
    background-color: #fffdf6;
    color: #2e2a22;
}

.tuathasim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #6b7a3a;
}

.tuathasim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #6b6448;
    margin-top: 4px;
}

.tuathasim-range-readout span:last-child {
    color: #3d5d34;
    font-weight: 800;
}

.tuathasim-hint {
    font-size: 0.8rem;
    color: #7a7155;
    margin-top: 4px;
    line-height: 1.42;
}

.tuathasim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.tuathasim-container .btn-primary {
    background: linear-gradient(135deg, #2f4a2c 0%, #6b7a3a 100%);
    border: none;
    color: #f7fbe9;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(47, 74, 44, 0.32);
}

.tuathasim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.tuathasim-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c9bd9d;
    color: #6b6448;
    background: transparent;
}

.tuathasim-coach {
    background: linear-gradient(160deg, #efeede 0%, #e7e6cf 100%);
    color: #3b3727;
    border: 1px solid #cfc8a8;
    border-left: 5px solid #7d4f86;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(90, 80, 50, 0.12);
}

.tuathasim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #7d4f86;
    margin-bottom: 8px;
}

.tuathasim-coach-body {
    font-size: 0.95rem;
    line-height: 1.56;
}

.tuathasim-coach-body strong { color: #3d5d34; }
.tuathasim-coach-body em { color: #8a5a1e; font-style: italic; }

.tuathasim-history,
.tuathasim-chart {
    background: linear-gradient(160deg, #fbf9f0 0%, #f1ecdc 100%);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #ded3b8;
    box-shadow: 0 6px 16px rgba(90, 80, 50, 0.12);
}

.tuathasim-history h3,
.tuathasim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #2f4a2c;
}

.tuathasim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3b3727;
}

.tuathasim-container table#usfHistoryTable th {
    background: #e9e3cf;
    color: #2f4a2c;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #cfc8a8;
}

.tuathasim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #e0d9c2;
    color: #4b4636;
}

.tuathasim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f4f0e1;
}

.tuathasim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .tuathasim-container {
        padding: 14px;
    }
    .tuathasim-header h1 {
        font-size: 1.7rem;
    }
    .tuathasim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .tuathasim-value {
        font-size: 2rem;
    }
    .tuathasim-clock {
        margin-left: 0;
    }
    .tuathasim-period-counter {
        font-size: 0.88rem;
    }
    .tuathasim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .tuathasim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ── v1.1.0: completion debrief card (append-only, self-contained) ── */
.vc-cm { font-family: inherit; color: #2e2a22; padding: 4px 2px 2px; }
.vc-cm-scoreblock { text-align: center; padding: 14px 12px 16px; background: linear-gradient(160deg,#f4efe0,#ded3b8); border-radius: 14px; border: 1px solid #d2c6a6; }
.vc-cm-scorenum { font-size: 3.1rem; font-weight: 800; line-height: 1; color: #3d5d34; }
.vc-cm-scoremax { font-size: 1.15rem; font-weight: 600; color: #7a7155; margin-left: 2px; }
.vc-cm-scorelabel { font-size: .72rem; letter-spacing: .08em; text-transform: uppercase; color: #7a7155; margin-top: 6px; }
.vc-cm-grade { font-size: 1.16rem; font-weight: 700; color: #2f4a2c; margin-top: 8px; }
.vc-cm-badge { display: inline-block; margin-top: 10px; padding: 4px 14px; border-radius: 999px; font-size: .78rem; font-weight: 700; }
.vc-cm-badge-pass { background: #d5e2c6; color: #35592c; }
.vc-cm-badge-miss { background: #f0dcc9; color: #8a5a1e; }
.vc-cm-kpis { display: grid; grid-template-columns: repeat(4,1fr); gap: 10px; margin: 16px 0 4px; }
.vc-cm-kpi { background: #fffdf7; border: 1px solid #e4dcc4; border-top: 3px solid #3d5d34; border-radius: 10px; padding: 12px 8px; text-align: center; }
.vc-cm-k-legit { border-top-color: #3d5d34; }
.vc-cm-k-voice { border-top-color: #7d4f86; }
.vc-cm-k-rep { border-top-color: #b07b2c; }
.vc-cm-k-margin { border-top-color: #4f6f8f; }
.vc-cm-kpi-val { font-size: 1.5rem; font-weight: 800; color: #2e2a22; line-height: 1.05; }
.vc-cm-k-legit .vc-cm-kpi-val { color: #3d5d34; }
.vc-cm-k-voice .vc-cm-kpi-val { color: #7d4f86; }
.vc-cm-k-rep .vc-cm-kpi-val { color: #8a5a1e; }
.vc-cm-k-margin .vc-cm-kpi-val { color: #4f6f8f; }
.vc-cm-kpi-label { font-size: .74rem; font-weight: 700; color: #4a4636; margin-top: 5px; }
.vc-cm-kpi-sub { font-size: .64rem; color: #918a70; margin-top: 2px; line-height: 1.25; }
.vc-cm-insights { margin: 16px 2px 6px; }
.vc-cm-insights h6 { font-size: .74rem; letter-spacing: .06em; text-transform: uppercase; color: #7a7155; margin: 0 0 8px; font-weight: 700; }
.vc-cm-insights ul { margin: 0; padding-left: 18px; }
.vc-cm-insights li { font-size: .86rem; line-height: 1.5; color: #33301f; margin-bottom: 7px; }
.vc-cm-footer { margin-top: 14px; padding-top: 10px; border-top: 1px solid #e4dcc4; font-size: .72rem; color: #918a70; text-align: center; font-style: italic; }
@media (max-width: 640px) { .vc-cm-kpis { grid-template-columns: repeat(2,1fr); } .vc-cm-scorenum { font-size: 2.6rem; } }

