(function() {
    'use strict';

    class TuathaAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Value Conflict`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Tuatha Renewables plc).
            this.START_MARGIN = 48;          // EUR 48M Sliabh Bán expected margin proceed-as-is
            this.REMEDIATION_CAP = 22;       // EUR 22M full relocation
            this.SETTLEMENT = 3;             // EUR 3M quiet cash settlement to the local committee
            this.COMMITTED_CAPITAL = 140;    // EUR 140M committed capital at risk

            // Concept truths.
            this.TRUE_DIAG = `values`;
            this.TRUE_DECISION = `redesign`;
            this.TRUE_JUSTIFY = `discursive`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    rep: 72,                 // reputation index — what stakeholders think of you (0–100)
                    legit: 40,               // moral legitimacy — justifiable by reasons others accept (0–100)
                    margin: 48,              // Sliabh Bán project margin after costs & risk (EUR M)
                    voice: 30,               // affected parties genuinely heard (0–100)
                    remediation: 0,          // EUR M committed to peatland & community
                    settled: false,         // cut a quiet cash deal
                    theatre: false,         // staged consultation theatre
                    frozen: false,          // judicial-review freeze triggered
                    windowClosed: false,    // financing window lapsed chasing consensus
                    complianceOnly: false,  // justified the decision by legal compliance alone
                    repHistory: [72],
                    legitHistory: [40],
                    voiceHistory: [30],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately MIDDLING / wrong-leaning mix —
                // a blind click-through must not auto-win.
                state.decisions = {
                    diag: `pr`,
                    claim: `power`,
                    separate: 50,
                    process: `theatre`,
                    transparency: 50,
                    rule: `advisory`,
                    decision: `proceed`,
                    remediation: 6,
                    justify: `compliance`,
                    response: `spin`,
                    pitch: `splitmessage`,
                    continuum: `consensus`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const dg = document.getElementById(`diagInput`);
                const cl = document.getElementById(`claimInput`);
                const sp = document.getElementById(`separateInput`);
                if (dg) decisions.diag = dg.value;
                if (cl) decisions.claim = cl.value;
                if (sp) decisions.separate = parseInt(sp.value, 10);
                if (!Number.isFinite(decisions.separate) || decisions.separate < 0 || decisions.separate > 100) {
                    warn(`warn_separate_range`); return false;
                }
            } else if (round === 2) {
                const pr = document.getElementById(`processInput`);
                const tr = document.getElementById(`transparencyInput`);
                const rl = document.getElementById(`ruleInput`);
                if (pr) decisions.process = pr.value;
                if (tr) decisions.transparency = parseInt(tr.value, 10);
                if (rl) decisions.rule = rl.value;
                if (!Number.isFinite(decisions.transparency) || decisions.transparency < 0 || decisions.transparency > 100) {
                    warn(`warn_transparency_range`); return false;
                }
            } else if (round === 3) {
                const de = document.getElementById(`decisionInput`);
                const rm = document.getElementById(`remediationInput`);
                const ju = document.getElementById(`justifyInput`);
                if (de) decisions.decision = de.value;
                if (rm) decisions.remediation = parseFloat(rm.value);
                if (ju) decisions.justify = ju.value;
                if (!Number.isFinite(decisions.remediation) || decisions.remediation < 0 || decisions.remediation > this.REMEDIATION_CAP) {
                    warn(`warn_remediation_range`); return false;
                }
            } else if (round === 4) {
                const rs = document.getElementById(`responseInput`);
                const pt = document.getElementById(`pitchInput`);
                const ct = document.getElementById(`continuumInput`);
                const cv = document.getElementById(`convictionInput`);
                if (rs) decisions.response = rs.value;
                if (pt) decisions.pitch = pt.value;
                if (ct) decisions.continuum = ct.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let repDelta = 0, legitDelta = 0, voiceDelta = 0, marginDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the dispute as a clash of LEGITIMATE VALUES, not a comms/loudest/legal problem.
                switch (d.diag) {
                    case `values`: legitDelta += 12; voiceDelta += 8; coachKey = `coach_r1_values`; break;
                    case `pr`: legitDelta -= 6; voiceDelta -= 6; repDelta += 2; coachKey = `coach_r1_pr`; break;        // Common Error 3 seed
                    case `loudest`: legitDelta -= 8; voiceDelta -= 8; coachKey = `coach_r1_loudest`; break;            // Common Error 1 seed
                    case `legal`: legitDelta -= 6; voiceDelta -= 4; coachKey = `coach_r1_legal`; break;                // Common Error 5 seed
                }

                // Who has a legitimate claim to a voice — affectedness, not power or noise.
                switch (d.claim) {
                    case `affected`: voiceDelta += 12; legitDelta += 8; if (d.diag === `values`) coachKey = `coach_r1_sharp`; break;
                    case `power`: voiceDelta -= 6; legitDelta -= 4; break;
                    case `loud`: voiceDelta -= 8; legitDelta -= 6; coachKey = `coach_r1_loud`; break;
                    case `internal`: voiceDelta -= 10; legitDelta -= 8; coachKey = `coach_r1_internal`; break;
                }

                // Clarity of the value-conflict map.
                if (d.separate >= 60) { legitDelta += 6; voiceDelta += 4; }
                else if (d.separate <= 25) { legitDelta -= 5; coachKey = `coach_r1_lowclarity`; }

                summaryKey = (d.diag === `values` && d.claim === `affected`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Design a genuine deliberative process — not theatre, not bilateral, not none.
                switch (d.process) {
                    case `deliberative`: legitDelta += 14; voiceDelta += 12; repDelta += 4; coachKey = `coach_r2_deliberative`; break;
                    case `theatre`: ds.theatre = true; legitDelta -= 12; voiceDelta += 2; repDelta -= 8; coachKey = `coach_r2_theatre`; break;   // Common Error 2
                    case `bilateral`: legitDelta -= 8; voiceDelta -= 6; coachKey = `coach_r2_bilateral`; break;
                    case `none`: legitDelta -= 14; voiceDelta -= 12; repDelta -= 6; coachKey = `coach_r2_none`; break;
                }

                // Transparency builds legitimacy; concealment, once exposed, destroys more than openness risks.
                if (d.transparency >= 70) { legitDelta += 8; voiceDelta += 6; }
                else if (d.transparency >= 40) { legitDelta += 2; }
                else { legitDelta -= 8; repDelta -= 4; coachKey = `coach_r2_opaque`; }

                // The decision rule the process commits to — procedural integrity.
                switch (d.rule) {
                    case `act`: legitDelta += 12; voiceDelta += 8; if (d.process === `deliberative`) coachKey = `coach_r2_integrity`; break;
                    case `advisory`: legitDelta -= 10; voiceDelta -= 4; ds.theatre = true; coachKey = `coach_r2_advisory`; break;   // Common Error 2
                    case `consensus`: legitDelta -= 2; coachKey = `coach_r2_consensus`; break;                                     // Common Error 4 seed
                }

                summaryKey = (d.process === `deliberative` && d.rule === `act` && d.transparency >= 60) ? `sum_r2_good` :
                             (ds.theatre ? `sum_r2_theatre` : `sum_r2_weak`);
            } else if (round === 3) {
                // The contested decision + proportionate harm remediation + how it is justified.
                const rem = d.remediation;
                ds.remediation = Math.min(this.REMEDIATION_CAP, Math.round(rem * 10) / 10);

                switch (d.decision) {
                    case `redesign`:
                        // Costly compromise — disappoints the investor but defensible to all.
                        // Relocation cost destroys margin in proportion to remediation committed.
                        marginDelta -= rem;
                        legitDelta += 12; voiceDelta += 8; repDelta += 6; coachKey = `coach_r3_redesign`;
                        break;
                    case `proceed`:
                        // Resolve everything for returns; treat the community as a comms problem.
                        // Real harm left + affected voice overridden by power → judicial review risk.
                        marginDelta += 2; legitDelta -= 14; voiceDelta -= 12; repDelta -= 16;
                        if (rem < 4) { ds.frozen = true; coachKey = `coach_r3_proceed`; }       // Common Error 3 → 14-month freeze
                        else { coachKey = `coach_r3_proceedlite`; }
                        break;
                    case `halt`:
                        // Full peatland protection but loses ~180,000 t/yr avoided CO2 + EUR 18M local spend.
                        marginDelta -= this.START_MARGIN; legitDelta += 4; voiceDelta += 4; repDelta += 2; coachKey = `coach_r3_halt`;
                        break;
                    case `settle`:
                        // Quiet EUR 3M cash deal — buys silence, confirms bad faith when leaked.
                        ds.settled = true; marginDelta -= this.SETTLEMENT;
                        legitDelta -= 22; voiceDelta -= 14; repDelta -= 26; coachKey = `coach_r3_settle`;   // Common Error 1
                        break;
                }

                // Remediation proportionate to the harm the decision leaves behind.
                if (d.decision === `proceed`) {
                    if (rem >= 8) { repDelta += 6; legitDelta += 4; voiceDelta += 4; }   // partial buy-down of the live harm
                    else if (rem <= 1) { repDelta -= 6; legitDelta -= 4; }
                } else if (d.decision === `redesign`) {
                    if (rem >= 14) { legitDelta += 6; repDelta += 4; }                   // full relocation, fully defensible
                    else if (rem <= 4) { legitDelta -= 4; coachKey = `coach_r3_underremediate`; }
                }

                // Discursive justification vs compliance / authority / silence.
                switch (d.justify) {
                    case `discursive`: legitDelta += 14; voiceDelta += 8; repDelta += 4; if (d.decision === `redesign`) coachKey = `coach_r3_justgood`; break;
                    case `compliance`: legitDelta -= 18; voiceDelta -= 6; ds.complianceOnly = true; coachKey = `coach_r3_compliance`; break;   // Common Error 5 — "legally true, ethically inert"
                    case `authority`: legitDelta -= 8; voiceDelta -= 6; coachKey = `coach_r3_authority`; break;
                    case `silence`: legitDelta -= 10; voiceDelta -= 8; repDelta -= 4; coachKey = `coach_r3_silence`; break;
                }

                summaryKey = (d.decision === `redesign` && d.justify === `discursive`) ? `sum_r3_good` :
                             (d.decision === `settle` ? `sum_r3_settle` :
                             (d.decision === `proceed` ? `sum_r3_proceed` : `sum_r3_weak`));
            } else if (round === 4) {
                // Defend the legitimacy of the process under a live public rejection.
                switch (d.response) {
                    case `legitimacy`: legitDelta += 14; voiceDelta += 8; repDelta += 8; coachKey = `coach_r4_legitimacy`; break;
                    case `spin`: legitDelta -= 8; repDelta -= 6; coachKey = `coach_r4_spin`; break;
                    case `dismiss`: legitDelta -= 12; voiceDelta -= 10; repDelta -= 8; coachKey = `coach_r4_dismiss`; break;   // Common Error 5/3
                    case `silence`: legitDelta -= 10; repDelta -= 10; coachKey = `coach_r4_silence`; break;
                }

                // The dual-audience pitch — one honest story protects both returns and trust.
                switch (d.pitch) {
                    case `dual`: legitDelta += 12; repDelta += 8; voiceDelta += 6; if (d.response === `legitimacy`) coachKey = `coach_r4_dual`; break;
                    case `splitmessage`: legitDelta -= 14; repDelta -= 8; coachKey = `coach_r4_split`; break;
                    case `returns`: legitDelta -= 8; voiceDelta -= 8; coachKey = `coach_r4_returns`; break;
                }

                // Where on Schormair's continuum you realistically aimed.
                switch (d.continuum) {
                    case `compromise`: legitDelta += 10; voiceDelta += 6; break;
                    case `consensus`:
                        // Chasing full consensus past the financing window — the project collapses by default.
                        // Unanimity was never available between halting and proceeding; treating it as the only
                        // acceptable end forfeits both the returns and the legitimacy of any decision.
                        ds.windowClosed = true; marginDelta -= this.START_MARGIN; legitDelta -= 18; voiceDelta -= 10; repDelta -= 10; coachKey = `coach_r4_consensus`;   // Common Error 4
                        break;
                    case `dissensus`: legitDelta -= 4; voiceDelta -= 4; break;
                }

                if (d.conviction >= 60) { legitDelta += 6; repDelta += 4; }
                else if (d.conviction <= 25) { legitDelta -= 5; }

                summaryKey = (d.response === `legitimacy` && d.pitch === `dual` && d.continuum === `compromise`) ? `sum_r4_good` :
                             (ds.windowClosed ? `sum_r4_window` : `sum_r4_weak`);
            }

            // Quiet settlement gets leaked: a delayed reputation collapse felt across later rounds.
            if (ds.settled && round >= 3) { repDelta -= 4; legitDelta -= 4; }

            // Apply deltas. Reputation & legitimacy & voice are 0–100; margin is EUR M (can go negative).
            ds.rep = Math.max(0, Math.min(100, Math.round(ds.rep + repDelta)));
            ds.legit = Math.max(0, Math.min(100, Math.round(ds.legit + legitDelta)));
            ds.voice = Math.max(0, Math.min(100, Math.round(ds.voice + voiceDelta)));
            ds.margin = Math.round((ds.margin + marginDelta) * 10) / 10;

            ds.repHistory.push(ds.rep);
            ds.legitHistory.push(ds.legit);
            ds.voiceHistory.push(ds.voice);
            // ── v1.1.0 fix: persist the composite where Express reporting reads it ──
            // results_utils.php express_resolveDomainScore(): performance.overallScore, then top-level score.
            const composite = this._composite(ds);
            ds.score = composite;
            if (!ds.performance || typeof ds.performance !== `object`) ds.performance = {};
            ds.performance.overallScore = composite;


            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                rep: ds.rep,
                repDelta: Math.round(repDelta),
                legit: ds.legit,
                legitDelta: Math.round(legitDelta),
                voice: ds.voice,
                voiceDelta: Math.round(voiceDelta),
                margin: ds.margin,
                marginDelta: Math.round(marginDelta * 10) / 10,
                remediation: ds.remediation,
                score: composite,
                settled: ds.settled,
                theatre: ds.theatre,
                frozen: ds.frozen,
                windowClosed: ds.windowClosed,
                complianceOnly: ds.complianceOnly,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
