        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const rep = Math.round(ds.rep);
            const legit = Math.round(ds.legit);
            const voice = Math.round(ds.voice);
            const margin = ds.margin;

            // Composite: legitimacy weighted highest (the pedagogical point), then voice and reputation,
            // plus a margin bonus (each EUR M worth ~0.5 pts, capped at ±20).
            const marginScore = Math.max(-20, Math.min(20, margin * 0.4));
            // Fatal-error penalty: the five classic collapses cost composite directly, so a
            // path that saturates the 0–100 KPIs can still NOT score well if one of them fired.
            // (Compliance-only justification is caught by the legitimacy weighting; the four
            // state flags below capture the leak, the theatre, the freeze and the missed window.)
            let collapsePenalty = 0;
            if (ds.settled) collapsePenalty += 22;       // quiet cash deal exposed as bad faith
            if (ds.frozen) collapsePenalty += 20;        // judicial-review freeze
            if (ds.windowClosed) collapsePenalty += 22;  // financing window lapsed chasing consensus
            if (ds.theatre) collapsePenalty += 14;       // consultation theatre, once read as such
            if (ds.complianceOnly) collapsePenalty += 12; // justified by legality alone — ethically inert
            const composite = Math.max(0, Math.round(
                legit * 0.40 + voice * 0.26 + rep * 0.20 + (marginScore + 20) * 0.35 - collapsePenalty
            ));

            // A genuinely defensible outcome cannot have fired any of the five classic errors.
            const cleanProcess = !(ds.settled || ds.theatre || ds.frozen || ds.windowClosed || ds.complianceOnly);
            const legitimate = legit >= 60 && !ds.complianceOnly;
            const heard = voice >= 55;
            const solvent = margin >= -5;
            const betrayedTrust = ds.settled || ds.theatre || ds.frozen || ds.windowClosed || ds.complianceOnly || rep <= 40;

            let performance = window.mySimulation.t(`grade_lost`);
            if (legitimate && heard && solvent && cleanProcess && composite >= 72) performance = window.mySimulation.t(`grade_defensible`);
            else if (legitimate && heard && cleanProcess) performance = window.mySimulation.t(`grade_processheld`);
            else if (ds.settled) performance = window.mySimulation.t(`grade_badfaith`);
            else if (ds.frozen) performance = window.mySimulation.t(`grade_freeze`);
            else if (ds.windowClosed) performance = window.mySimulation.t(`grade_window`);
            else if (ds.complianceOnly) performance = window.mySimulation.t(`grade_compliance`);
            else if (composite >= 52) performance = window.mySimulation.t(`grade_contested`);

            const insights = [];
            if (legitimate && heard && solvent) insights.push(window.mySimulation.t(`insight_legitimate`));
            else if (ds.settled) insights.push(window.mySimulation.t(`insight_settled`));
            else if (ds.frozen) insights.push(window.mySimulation.t(`insight_frozen`));
            else if (ds.windowClosed) insights.push(window.mySimulation.t(`insight_window`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (rep >= 65 && legit < 50) insights.push(window.mySimulation.t(`insight_popular_illegit`));
            if (legit >= 65 && rep < 55) insights.push(window.mySimulation.t(`insight_unpopular_legit`));
            if (ds.theatre) insights.push(window.mySimulation.t(`insight_theatre`));
            if (margin < -10) insights.push(window.mySimulation.t(`insight_margin`));
            if (voice >= 65 && legit >= 65) insights.push(window.mySimulation.t(`insight_voice`));

            return {
                rep: rep,
                legit: legit,
                voice: voice,
                margin: margin,
                legitimate: legitimate,
                heard: heard,
                solvent: solvent,
                betrayedTrust: betrayedTrust,
                composite: composite,
                performance: performance,
                insights: insights
            };
        }

        // ── v1.1.0 fix: persist composite score + localized completion debrief ──
        _composite(ds) {
            // Verbatim mirror of getPerformanceSummary()'s composite (incl. collapse penalties).
            const rep = Math.round(ds.rep || 0);
            const legit = Math.round(ds.legit || 0);
            const voice = Math.round(ds.voice || 0);
            const margin = (ds.margin != null) ? ds.margin : 0;
            const marginScore = Math.max(-20, Math.min(20, margin * 0.4));
            let collapsePenalty = 0;
            if (ds.settled) collapsePenalty += 22;
            if (ds.frozen) collapsePenalty += 20;
            if (ds.windowClosed) collapsePenalty += 22;
            if (ds.theatre) collapsePenalty += 14;
            if (ds.complianceOnly) collapsePenalty += 12;
            return Math.max(0, Math.round(
                legit * 0.40 + voice * 0.26 + rep * 0.20 + (marginScore + 20) * 0.35 - collapsePenalty
            ));
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            const s = summary || {};
            const composite = (typeof s.composite === `number`) ? s.composite : 0;
            const grade = s.performance || ``;
            const held = !!(s.legitimate && s.heard && s.solvent);
            const rep = (s.rep != null) ? s.rep : 0;
            const legit = (s.legit != null) ? s.legit : 0;
            const voice = (s.voice != null) ? s.voice : 0;
            const margin = (s.margin != null) ? s.margin : 0;
            const insights = Array.isArray(s.insights) ? s.insights : [];

            const badgeClass = held ? `vc-cm-badge-pass` : `vc-cm-badge-miss`;
            const badgeText = held ? t(`cm_badge_beat`) : t(`cm_badge_missed`);

            const kpi = (label, val, sub, cls) => `
                <div class="vc-cm-kpi ${cls}">
                    <div class="vc-cm-kpi-val">${val}</div>
                    <div class="vc-cm-kpi-label">${label}</div>
                    <div class="vc-cm-kpi-sub">${sub}</div>
                </div>`;

            let insightHtml = ``;
            insights.forEach((it) => { insightHtml += `<li>${it}</li>`; });

            return `
                <div class="vc-cm">
                    <div class="vc-cm-scoreblock">
                        <div class="vc-cm-scorenum">${composite}<span class="vc-cm-scoremax">/100</span></div>
                        <div class="vc-cm-scorelabel">${t(`cm_score_label`)}</div>
                        <div class="vc-cm-grade">${grade}</div>
                        <span class="vc-cm-badge ${badgeClass}">${badgeText}</span>
                    </div>
                    <div class="vc-cm-kpis">
                        ${kpi(t(`legit_label`), legit, t(`legit_sub`), `vc-cm-k-legit`)}
                        ${kpi(t(`voice_label`), voice, t(`voice_sub`), `vc-cm-k-voice`)}
                        ${kpi(t(`rep_label`), rep, t(`rep_sub`), `vc-cm-k-rep`)}
                        ${kpi(t(`margin_label`), `EUR ` + margin + `M`, t(`margin_sub`), `vc-cm-k-margin`)}
                    </div>
                    ${insightHtml ? `<div class="vc-cm-insights"><h6>${t(`cm_insights_title`)}</h6><ul>${insightHtml}</ul></div>` : ``}
                    <div class="vc-cm-footer">${t(`cm_footer`)}</div>
                </div>`;
        }

